        // - Case 2: [a-f]
        // - Case 3: [A-F]
        // - otherwise not supported
        unchecked {
            if (value > 47 && value < 58) value -= 48;
            else if (value > 96 && value < 103) value -= 87;
            else if (value > 64 && value < 71) value -= 55;
            else return type(uint8).max;
        }

        return value;
    }

    /**
     * @dev Escape special characters in JSON strings. This can be useful to prevent JSON injection in NFT metadata.
     *
     * WARNING: This function should only be used in double quoted JSON strings. Single quotes are not escaped.
     *
     * NOTE: This function escapes backslashes (including those in \uXXXX sequences) and the characters in ranges
     * defined in section 2.5 of RFC-4627 (U+0000 to U+001F, U+0022 and U+005C). All control characters in U+0000
     * to U+001F are escaped (\b, \t, \n, \f, \r use short form; others use \u00XX). ECMAScript's `JSON.parse` does
     * recover escaped unicode characters that are not in this range, but other tooling may provide different results.
     */
    function escapeJSON(string memory input) internal pure returns (string memory) {
        bytes memory buffer = bytes(input);

        // Put output at the FMP. Memory will be reserved later when we figure out the actual length of the escaped
        // string. All write are done using _unsafeWriteBytesOffset, which avoid the (expensive) length checks for
        // each character written.
        bytes memory output;
        assembly ("memory-safe") {
            output := mload(0x40)
        }
        uint256 outputLength = 0;

        for (uint256 i = 0; i < buffer.length; ++i) {
            uint8 char = uint8(bytes1(_unsafeReadBytesOffset(buffer, i)));
            if (((SPECIAL_CHARS_LOOKUP & (1 << char)) != 0)) {
                _unsafeWriteBytesOffset(output, outputLength++, "\\");
                if (char == 0x08) _unsafeWriteBytesOffset(output, outputLength++, "b");
                else if (char == 0x09) _unsafeWriteBytesOffset(output, outputLength++, "t");
                else if (char == 0x0a) _unsafeWriteBytesOffset(output, outputLength++, "n");
                else if (char == 0x0c) _unsafeWriteBytesOffset(output, outputLength++, "f");
                else if (char == 0x0d) _unsafeWriteBytesOffset(output, outputLength++, "r");
                else if (char == 0x5c) _unsafeWriteBytesOffset(output, outputLength++, "\\");
                else if (char == 0x22) {
                    // solhint-disable-next-line quotes
                    _unsafeWriteBytesOffset(output, outputLength++, '"');
                } else {
                    // U+0000 to U+001F without short form: output \u00XX
                    _unsafeWriteBytesOffset(output, outputLength++, "u");
                    _unsafeWriteBytesOffset(output, outputLength++, "0");
                    _unsafeWriteBytesOffset(output, outputLength++, "0");
                    _unsafeWriteBytesOffset(output, outputLength++, HEX_DIGITS[char >> 4]);
                    _unsafeWriteBytesOffset(output, outputLength++, HEX_DIGITS[char & 0x0f]);
                }
            } else {
                _unsafeWriteBytesOffset(output, outputLength++, bytes1(char));
            }
        }
        // write the actual length and reserve memory
        assembly ("memory-safe") {
            mstore(output, outputLength)
            mstore(0x40, add(output, add(outputLength, 0x20)))
        }

        return string(output);
    }

    /**
     * @dev Reads a bytes32 from a bytes array without bounds checking.
     *
     * NOTE: making this function internal would mean it could be used with memory unsafe offset, and marking the
     * assembly block as such would prevent some optimizations.
     */
    function _unsafeReadBytesOffset(bytes memory buffer, uint256 offset) private pure returns (bytes32 value) {
        // This is not memory safe in the general case, but all calls to this private function are within bounds.
        assembly ("memory-safe") {
            value := mload(add(add(buffer, 0x20), offset))
        }
    }

    /**
     * @dev Write a bytes1 to a bytes array without bounds checking.
     *
     * NOTE: making this function internal would mean it could be used with memory unsafe offset, and marking the
     * assembly block as such would prevent some optimizations.
     */
    function _unsafeWriteBytesOffset(bytes memory buffer, uint256 offset, bytes1 value) private pure {
        // This is not memory safe in the general case, but all calls to this private function are within bounds.
        assembly ("memory-safe") {
            mstore8(add(add(buffer, 0x20), offset), shr(248, value))
        }
    }
}

contracts/BountyEscrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title BountyEscrow - 智能合约悬赏系统
 * @notice "Your boss can't stiff you anymore. Code is Law. 
 *          But the tokens might still be worthless."
 * @dev Task bounty system where $NIUMA tokens are locked in escrow.
 *      Boss creates bounty → Worker claims → Completion triggers payout.
 */
contract BountyEscrow is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    enum BountyStatus { Open, Claimed, Completed, Cancelled }

    struct Bounty {
        uint256 id;
        address creator;
        address worker;
        uint256 amount;
        string description;
        BountyStatus status;
        uint256 createdAt;
        uint256 completedAt;
    }

    IERC20 public immutable niuMaCoin;
    uint256 public nextBountyId;

    mapping(uint256 => Bounty) public bounties;
    uint256[] public bountyIds;

    // Track bounties by creator and worker
    mapping(address => uint256[]) public creatorBounties;
    mapping(address => uint256[]) public workerBounties;

    event BountyCreated(uint256 indexed bountyId, address indexed creator, uint256 amount, string description);
    event BountyClaimed(uint256 indexed bountyId, address indexed worker);
    event BountyCompleted(uint256 indexed bountyId, address indexed worker, uint256 amount);
    event BountyCancelled(uint256 indexed bountyId, address indexed creator, uint256 refundAmount);

    constructor(address _niuMaCoin) Ownable(msg.sender) {
        niuMaCoin = IERC20(_niuMaCoin);
    }

    /**
     * @notice Create a new bounty and lock $NIUMA tokens in escrow.
     *         "Put your money where your mouth is, boss."
     * @param description Task description (e.g., "Fix the prod bug at 3 AM")
     * @param amount Amount of $NIUMA to lock as reward
     */
    function createBounty(string calldata description, uint256 amount) external nonReentrant {
        require(amount > 0, "Bounty: reward must be > 0, we're not slaves");
        require(bytes(description).length > 0, "Bounty: describe the task, boss");

        // Transfer tokens from creator to this contract (escrow)
        niuMaCoin.safeTransferFrom(msg.sender, address(this), amount);

        uint256 bountyId = nextBountyId++;
        bounties[bountyId] = Bounty({
            id: bountyId,
            creator: msg.sender,
            worker: address(0),
            amount: amount,
            description: description,
            status: BountyStatus.Open,
            createdAt: block.timestamp,
            completedAt: 0
        });
        bountyIds.push(bountyId);
        creatorBounties[msg.sender].push(bountyId);

        emit BountyCreated(bountyId, msg.sender, amount, description);
    }

    /**
     * @notice Claim an open bounty. "I'll take on the suffering."
     * @param bountyId The bounty to claim
     */
    function claimBounty(uint256 bountyId) external {
        Bounty storage b = bounties[bountyId];
        require(b.status == BountyStatus.Open, "Bounty: not open, someone beat you to the misery");
        require(b.creator != msg.sender, "Bounty: can't claim your own bounty, nice try boss");

        b.status = BountyStatus.Claimed;
        b.worker = msg.sender;
        workerBounties[msg.sender].push(bountyId);

        emit BountyClaimed(bountyId, msg.sender);
    }

    /**
     * @notice Complete a bounty and release tokens to the worker.
     *         Only the bounty creator (boss) can approve completion.
     *         "Code is Law: payment is instant. Unlike your last employer."
     * @param bountyId The bounty to complete
     */
    function completeBounty(uint256 bountyId) external nonReentrant {
        Bounty storage b = bounties[bountyId];
        require(b.status == BountyStatus.Claimed, "Bounty: not claimed yet");
        require(b.creator == msg.sender || owner() == msg.sender, "Bounty: only creator or admin can approve");

        b.status = BountyStatus.Completed;
        b.completedAt = block.timestamp;

        // Transfer tokens from escrow to worker. Instant. No 30-day payment terms.
        niuMaCoin.safeTransfer(b.worker, b.amount);

        emit BountyCompleted(bountyId, b.worker, b.amount);
    }

    /**
     * @notice Cancel an open bounty and refund tokens.
     *         Can only cancel if no one has claimed it yet.
     * @param bountyId The bounty to cancel
     */
    function cancelBounty(uint256 bountyId) external nonReentrant {
        Bounty storage b = bounties[bountyId];
        require(b.status == BountyStatus.Open, "Bounty: can only cancel open bounties");
        require(b.creator == msg.sender, "Bounty: only creator can cancel");

        b.status = BountyStatus.Cancelled;

        // Refund tokens to creator
        niuMaCoin.safeTransfer(b.creator, b.amount);

        emit BountyCancelled(bountyId, b.creator, b.amount);
    }

    /**
     * @notice Get total number of bounties.
     */
    function getBountyCount() external view returns (uint256) {
        return nextBountyId;
    }

    /**
     * @notice Get all bounty IDs.
     */
    function getAllBountyIds() external view returns (uint256[] memory) {
        return bountyIds;
    }

    /**
     * @notice Get bounties created by an address.
     */
    function getCreatorBounties(address creator) external view returns (uint256[] memory) {
        return creatorBounties[creator];
    }

    /**
     * @notice Get bounties claimed by a worker.
     */
    function getWorkerBounties(address worker) external view returns (uint256[] memory) {
        return workerBounties[worker];
    }

    /**
     * @notice Get bounty details.
     */
    function getBounty(uint256 bountyId) external view returns (
        address creator,
        address worker,
        uint256 amount,
        string memory description,
        BountyStatus status,
        uint256 createdAt,
        uint256 completedAt
    ) {
        Bounty storage b = bounties[bountyId];
        return (b.creator, b.worker, b.amount, b.description, b.status, b.createdAt, b.completedAt);
    }
}

contracts/DailyPOAP.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title DailyPOAP - 带薪拉屎凭证 (Proof of Attendance Protocol)
 * @notice "Your attendance is now immutable. No more 'the subway was delayed' excuses."
 * @dev ERC-1155 contract where each token ID represents a day (YYYYMMDD format).
 *      Employees clock in by minting a daily POAP NFT.
 *      Late arrivals (after 9:00 AM UTC) get their deposit slashed.
 */
contract DailyPOAP is ERC1155, Ownable {
    using Strings for uint256;

    // 9:00 AM UTC in seconds from midnight
    uint256 public constant CLOCK_IN_DEADLINE = 9 * 3600; // 32400 seconds

    // Slashing penalty for late clock-in (0.001 ETH)
    uint256 public constant LATE_PENALTY = 0.001 ether;

    // Employee deposits (staked ETH for accountability)
    mapping(address => uint256) public deposits;

    // Track daily clock-ins: address => dayId => bool
    mapping(address => mapping(uint256 => bool)) public hasClocked;

    // Track total clock-ins per address
    mapping(address => uint256) public totalClockIns;

    // Track all clock-in records for an address
    mapping(address => uint256[]) public clockInHistory;

    // Base URI for metadata
    string public baseUri;

    event ClockIn(address indexed employee, uint256 indexed dayId, bool onTime, uint256 timestamp);
    event Deposited(address indexed employee, uint256 amount);
    event Slashed(address indexed employee, uint256 amount, string reason);
    event Withdrawn(address indexed employee, uint256 amount);

    constructor(string memory _baseUri) ERC1155(_baseUri) Ownable(msg.sender) {
        baseUri = _baseUri;
    }

    /**
     * @notice Get today's day ID in YYYYMMDD format.
     * @dev Uses block.timestamp. Not perfect but good enough for Meme purposes.
     */
    function getTodayId() public view returns (uint256) {
        return _timestampToDayId(block.timestamp);
    }

    /**
     * @notice Convert a timestamp to YYYYMMDD format.
     */
    function _timestampToDayId(uint256 timestamp) internal pure returns (uint256) {
        // Simple date calculation (good enough for demo, not production-grade)
        uint256 z = timestamp / 86400 + 719468;
        uint256 era = z / 146097;
        uint256 doe = z - era * 146097;
        uint256 yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
        uint256 y = yoe + era * 400;
        uint256 doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
        uint256 mp = (5 * doy + 2) / 153;
        uint256 d = doy - (153 * mp + 2) / 5 + 1;
        uint256 m = mp + (mp < 10 ? 3 : uint256(0) - 9);
        if (m <= 2) y += 1;

        return y * 10000 + m * 100 + d;
    }

    /**
     * @notice Deposit ETH as your "accountability stake".
     *         Think of it as your dignity deposit.
     */
    function deposit() external payable {
        require(msg.value > 0, "POAP: deposit something, cheapskate");
        deposits[msg.sender] += msg.value;
        emit Deposited(msg.sender, msg.value);
    }

    /**
     * @notice ⛏️ CLOCK IN - Mint your daily "带薪拉屎凭证"
     *         This is literally mining. You mine your attendance NFT.
     *         Late? Your deposit gets slashed. Code is Law.
     */
    function clockIn() external {
        uint256 dayId = getTodayId();
        require(!hasClocked[msg.sender][dayId], "POAP: already clocked in today, no double overtime");

        hasClocked[msg.sender][dayId] = true;
        totalClockIns[msg.sender] += 1;
        clockInHistory[msg.sender].push(dayId);

        // Check if late (after 9 AM UTC)
        uint256 secondsInDay = block.timestamp % 86400;
        bool onTime = secondsInDay <= CLOCK_IN_DEADLINE;

        // Slash if late and has deposit
        if (!onTime && deposits[msg.sender] > 0) {
            uint256 penalty = deposits[msg.sender] >= LATE_PENALTY 
                ? LATE_PENALTY 
                : deposits[msg.sender];
            deposits[msg.sender] -= penalty;
            // Penalty goes to contract owner (the Boss always wins)
            (bool sent, ) = owner().call{value: penalty}("");
            require(sent, "POAP: slashing transfer failed");
            emit Slashed(msg.sender, penalty, "Late clock-in: Code is Law");
        }

        // Mint the POAP NFT
        _mint(msg.sender, dayId, 1, "");

        emit ClockIn(msg.sender, dayId, onTime, block.timestamp);
    }

    /**
     * @notice Withdraw your remaining deposit. Only when you quit.
     */
    function withdrawDeposit() external {
        uint256 amount = deposits[msg.sender];
        require(amount > 0, "POAP: nothing to withdraw, you're broke");
        deposits[msg.sender] = 0;
        (bool sent, ) = msg.sender.call{value: amount}("");
        require(sent, "POAP: withdrawal failed");
        emit Withdrawn(msg.sender, amount);
    }

    /**
     * @notice Get clock-in history for an address.
     */
    function getClockInHistory(address employee) external view returns (uint256[] memory) {
        return clockInHistory[employee];
    }

    /**
     * @notice Check if an address has clocked in today.
     */
    function hasClockedToday(address employee) external view returns (bool) {
        return hasClocked[employee][getTodayId()];
    }

    /**
     * @notice Update base URI for metadata.
     */
    function setBaseUri(string memory _baseUri) external onlyOwner {
        baseUri = _baseUri;
        _setURI(_baseUri);
    }

    /**
     * @notice Returns the URI for a given token ID.
     */
    function uri(uint256 tokenId) public view override returns (string memory) {
        return string(abi.encodePacked(baseUri, tokenId.toString(), ".json"));
    }
}

contracts/DegenOffice.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";

/**
 * @title DegenOffice - 去中心化办公室总控合约
 * @notice "Welcome to the future of work. Where your boss is a smart contract,
 *          and the exit strategy is built into the codebase."
 * @dev Main office controller handling:
 *      - NFT-gated role-based access (RBAC via BAYC/Pudgy balanceOf)
 *      - Company fund management
 *      - The legendary Rug Pull™ feature
 */
contract DegenOffice is Ownable {

    // Role definitions
    enum Role { 
        NiuMa,      // 🐂 底层牛马 (Liquidity Provider) - balance = 0
        Employee,   // 👔 普通员工 - has some ETH
        Manager,    // 🎩 经理 - has NFTs but not premium
        CEO         // 🦍 CEO / 董事会 - has BAYC or Pudgy
    }

    // NFT contract addresses for role gating (Sepolia testnet versions)
    address public baycContract;   // Bored Ape Yacht Club (or testnet equivalent)
    address public pudgyContract;  // Pudgy Penguins (or testnet equivalent)

    // Company fund
    uint256 public totalFunding;

    // Track employees
    mapping(address => bool) public isRegistered;
    address[] public employees;

    // The $NIUMA token
    IERC20 public niuMaCoin;

    // Rug pull status
    bool public hasRugPulled;

    event EmployeeRegistered(address indexed employee, Role role);
    event FundDeposited(address indexed from, uint256 amount);
    event RugPullExecuted(address indexed boss, uint256 ethAmount, uint256 tokenAmount, string message);
    event NFTContractsUpdated(address bayc, address pudgy);

    constructor(
        address _niuMaCoin,
        address _baycContract,
        address _pudgyContract
    ) Ownable(msg.sender) {
        niuMaCoin = IERC20(_niuMaCoin);
        baycContract = _baycContract;
        pudgyContract = _pudgyContract;
    }

    /**
     * @notice Determine a wallet's role based on their assets.
     *         "In Web3, your net worth IS your title."
     * @param wallet The address to check
     * @return role The assigned role
     */
    function getRole(address wallet) public view returns (Role) {
        // Check for BAYC or Pudgy NFTs → CEO
        if (baycContract != address(0)) {
            try IERC721(baycContract).balanceOf(wallet) returns (uint256 balance) {
                if (balance > 0) return Role.CEO;
            } catch {}
        }
        if (pudgyContract != address(0)) {
            try IERC721(pudgyContract).balanceOf(wallet) returns (uint256 balance) {
                if (balance > 0) return Role.CEO;
            } catch {}
        }

        // Check $NIUMA balance for manager status
        uint256 tokenBalance = 0;
        try niuMaCoin.balanceOf(wallet) returns (uint256 bal) {
            tokenBalance = bal;
        } catch {}

        if (tokenBalance >= 50_000 * 1e18) return Role.Manager;

        // Check ETH balance
        if (wallet.balance > 0 || tokenBalance > 0) return Role.Employee;

        // No assets = 牛马
        return Role.NiuMa;
    }

    /**
     * @notice Get role name as string for frontend display.
     */
    function getRoleName(address wallet) external view returns (string memory) {
        Role role = getRole(wallet);
        if (role == Role.CEO) return unicode"🦍 CEO / 董事会";
        if (role == Role.Manager) return unicode"🎩 经理";
        if (role == Role.Employee) return unicode"👔 员工";
        return unicode"🐂 底层牛马 (Liquidity Provider)";
    }

    /**
     * @notice Register as an employee. Your wallet IS your employee ID.
     */
    function register() external {
        require(!isRegistered[msg.sender], "Office: already registered, no double employment");
        isRegistered[msg.sender] = true;
        employees.push(msg.sender);
        emit EmployeeRegistered(msg.sender, getRole(msg.sender));
    }

    /**
     * @notice Deposit ETH into company fund. "Company team building budget."
     */
    function depositFund() external payable {
        require(msg.value > 0, "Office: deposit something");
        totalFunding += msg.value;
        emit FundDeposited(msg.sender, msg.value);
    }

    /**
     * @notice Update NFT contract addresses (for testnet flexibility).
     */
    function setNFTContracts(address _bayc, address _pudgy) external onlyOwner {
        baycContract = _bayc;
        pudgyContract = _pudgy;
        emit NFTContractsUpdated(_bayc, _pudgy);
    }

    /**
     * @notice 🚨 EXECUTE RUG PULL 🚨
     *         "Smart contract successfully drained. WAGMI."
     *         
     *         Drains all ETH and $NIUMA from the contract to the owner.
     *         This is the nuclear option. The blockchain remembers everything.
     *         
     *         Only the owner (boss) can execute this.
     *         Can only be executed once (even villains have standards).
     */
    function rugPull() external onlyOwner {
        require(!hasRugPulled, "Office: already rug pulled, can't rug twice");
        hasRugPulled = true;

        uint256 ethBalance = address(this).balance;
        uint256 tokenBalance = niuMaCoin.balanceOf(address(this));

        // Drain ETH
        if (ethBalance > 0) {
            (bool sent, ) = owner().call{value: ethBalance}("");
            require(sent, "Office: ETH drain failed");
        }

        // Drain tokens
        if (tokenBalance > 0) {
            niuMaCoin.transfer(owner(), tokenBalance);
        }

        totalFunding = 0;

        emit RugPullExecuted(
            owner(), 
            ethBalance, 
            tokenBalance, 
            "Smart contract successfully drained. WAGMI."
        );
    }

    /**
     * @notice Get company stats for the dashboard.
     */
    function getCompanyStats() external view returns (
        uint256 ethBalance,
        uint256 tokenBalance,
        uint256 employeeCount,
        bool rugPulled
    ) {
        return (
            address(this).balance,
            niuMaCoin.balanceOf(address(this)),
            employees.length,
            hasRugPulled
        );
    }

    /**
     * @notice Get all registered employee addresses.
     */
    function getEmployees() external view returns (address[] memory) {
        return employees;
    }

    // Accept ETH deposits
    receive() external payable {
        totalFunding += msg.value;
        emit FundDeposited(msg.sender, msg.value);
    }
}

contracts/NiuMaCoin.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title NiuMaCoin ($NIUMA) - 牛马币
 * @notice The official salary token of Degen-Office.
 *         "Your labor is priceless, but your token might be worthless."
 * @dev ERC-20 token with faucet for testnet usage and owner minting for bounties.
 */
contract NiuMaCoin is ERC20, Ownable {

    uint256 public constant FAUCET_AMOUNT = 10_000 * 1e18;   // 10,000 tokens per claim
    uint256 public constant MAX_SUPPLY    = 1_000_000_000 * 1e18; // 1 billion total

    mapping(address => bool) public hasClaimed;

    event FaucetClaimed(address indexed user, uint256 amount);

    constructor() ERC20("NiuMa Coin", "NIUMA") Ownable(msg.sender) {
        // Mint initial supply to deployer (the Boss)
        _mint(msg.sender, 100_000_000 * 1e18); // 100M to the boss
    }

    /**
     * @notice Mint tokens for bounty funding. Only the boss can do this.
     * @param to Recipient address
     * @param amount Amount to mint (in wei)
     */
    function mint(address to, uint256 amount) external onlyOwner {
        require(totalSupply() + amount <= MAX_SUPPLY, "NIUMA: max supply exceeded, even the printer has limits");
        _mint(to, amount);
    }

    /**
     * @notice Free tokens! Because your boss won't give you a raise.
     *         Each address can claim once. 10,000 $NIUMA per claim.
     */
    function faucet() external {
        require(!hasClaimed[msg.sender], "NIUMA: already claimed, no double-dipping");
        require(totalSupply() + FAUCET_AMOUNT <= MAX_SUPPLY, "NIUMA: faucet dried up");

        hasClaimed[msg.sender] = true;
        _mint(msg.sender, FAUCET_AMOUNT);

        emit FaucetClaimed(msg.sender, FAUCET_AMOUNT);
    }

    /**
     * @notice Burn your own tokens. For when you realize they're worthless.
     * @param amount Amount to burn
     */
    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
    }
}

